set-variable.value:
@{       try {         var settings = JObject.Parse((string)context.Variables["documentSettings"]);         var model = (string)context.Variables["documentModel"];         if (context.Request.Url.Query.Count != 1 || !context.Request.Url.Query.ContainsKey("model") || context.Request.Url.Query["model"].Length != 1 || !((JArray)settings["allowedModels"]).Any(m => (string)m == model)) { return 400; }         if (context.Request.Headers.GetValueOrDefault("Content-Encoding", "identity") != "identity") { return 415; }         var mime = context.Request.Headers.GetValueOrDefault("Content-Type", "").Split(';')[0].Trim().ToLowerInvariant();         if (!((JArray)settings["contentTypes"]).Any(t => (string)t == mime)) { return 415; }         if (context.Request.Body == null) { return 400; }         var bytes = context.Request.Body.As<byte[]>(preserveContent: true);         if (bytes.Length > (int)settings["maxRequestBytes"]) { return 413; }         if (mime == "text/html") { return bytes.Length == 0 ? 400 : 200; } if (bytes.Length < 8) { return 400; }         var pdf = bytes[0] == 37 && bytes[1] == 80 && bytes[2] == 68 && bytes[3] == 70 && bytes[4] == 45;         var jpeg = bytes[0] == 255 && bytes[1] == 216 && bytes[2] == 255;         var png = bytes[0] == 137 && bytes[1] == 80 && bytes[2] == 78 && bytes[3] == 71 && bytes[4] == 13 && bytes[5] == 10 && bytes[6] == 26 && bytes[7] == 10;         var tiff = (bytes[0] == 73 && bytes[1] == 73 && bytes[2] == 42 && bytes[3] == 0) || (bytes[0] == 77 && bytes[1] == 77 && bytes[2] == 0 && bytes[3] == 42);         var bmp = bytes[0] == 66 && bytes[1] == 77;
        var zip = bytes[0] == 80 && bytes[1] == 75 && bytes[2] == 3 && bytes[3] == 4;
        var heif = bytes.Length >= 12 && bytes[4] == 102 && bytes[5] == 116 && bytes[6] == 121 && bytes[7] == 112;
        var office = mime == "application/vnd.openxmlformats-officedocument.wordprocessingml.document" || mime == "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" || mime == "application/vnd.openxmlformats-officedocument.presentationml.presentation";         return ((mime == "application/pdf" && pdf) || (mime == "image/jpeg" && jpeg) || (mime == "image/png" && png) || (mime == "image/tiff" && tiff) || (mime == "image/bmp" && bmp) || (office && zip) || ((mime == "image/heif" || mime == "image/heic") && heif) || mime == "text/html") ? 200 : 400;       } catch { return 400; }     }

@{
      try {
        var response = context.Response;
        if (response == null || response.StatusCode != 202) { return ""; }
        var baseUrl = (string)context.Variables["documentBaseUrl"];
        var location = new Uri(response.Headers.GetValueOrDefault("Operation-Location", ""));
        var expected = new Uri(baseUrl);
        var prefix = "/documentintelligence/documentModels/" + (string)context.Variables["documentModel"] + "/analyzeResults/";
        if (location.Scheme != "https" || !String.Equals(location.Authority, expected.Authority, StringComparison.OrdinalIgnoreCase) || location.UserInfo.Length != 0 || location.Fragment.Length != 0 || !location.AbsolutePath.StartsWith(prefix, StringComparison.Ordinal) || location.Query != "?api-version=2024-11-30") { return ""; }
        Guid id;
        if (!Guid.TryParseExact(location.AbsolutePath.Substring(prefix.Length), "D", out id)) { return ""; }
        return id.ToString("D");
      } catch { return ""; }
    }

@{
      try {
        var id = (string)context.Variables["documentOperationId"];
        if (String.IsNullOrEmpty(id) || context.Subscription == null || String.IsNullOrWhiteSpace(context.Subscription.Id)) { return ""; }
        var model = (string)context.Variables["documentModel"];
        var issued = (long)context.Variables["documentStartedAt"];
        /* Analyze結果の保持は提供元の受付から24時間です。独自の短い処理期限は設けません。 */
        var expires = issued + 86400;
        string scope;
        using (var hash = System.Security.Cryptography.SHA256.Create()) {
          scope = Convert.ToBase64String(hash.ComputeHash(System.Text.Encoding.UTF8.GetBytes((string)context.Variables["documentBaseUrl"] + "\n" + context.Api.Id + "\n" + context.Subscription.Id)));
        }
        var claims = new JObject(new JProperty("v", 1), new JProperty("aud", "document-analysis-v1"), new JProperty("operationId", id), new JProperty("model", model), new JProperty("scope", scope), new JProperty("iat", issued), new JProperty("exp", expires));
        var encoded = Convert.ToBase64String(System.Text.Encoding.UTF8.GetBytes(claims.ToString(Newtonsoft.Json.Formatting.None))).TrimEnd('=').Replace('+', '-').Replace('/', '_');
        string signature;
        using (var hmac = new System.Security.Cryptography.HMACSHA256(System.Text.Encoding.UTF8.GetBytes("{{core-realtime-ticket-key}}"))) {
          /* 同じ鍵のRealtimeチケットと、署名対象を明確に分離します。 */
          signature = Convert.ToBase64String(hmac.ComputeHash(System.Text.Encoding.UTF8.GetBytes("document-analysis-v1:" + encoded))).TrimEnd('=').Replace('+', '-').Replace('/', '_');
        }
        return new JObject(new JProperty("operationId", id), new JProperty("model", model), new JProperty("status", "running"), new JProperty("statusPath", "/tools/documents/v1/operations/" + id), new JProperty("ticket", encoded + "." + signature), new JProperty("expiresAt", DateTimeOffset.FromUnixTimeSeconds(expires).UtcDateTime.ToString("o")), new JProperty("requestId", context.RequestId.ToString())).ToString(Newtonsoft.Json.Formatting.None);
      } catch { return ""; }
    }

@{
      var response = context.Response;
      if (response == null) { return 504; }
      if (response.StatusCode == 429) { return 429; }
      if (response.StatusCode == 413) { return 413; }
      if (response.StatusCode == 400 || response.StatusCode == 415 || response.StatusCode == 422) { return 422; }
      return String.IsNullOrEmpty((string)context.Variables["documentAccepted"]) ? 502 : 202;
    }

@{
      int delay;
      return context.Response != null && Int32.TryParse(context.Response.Headers.GetValueOrDefault("Retry-After", ""), out delay) && delay > 0 && delay <= 86400 ? delay : 2;
    }
